\coordinate (D) at (1.2,2.4);
\coordinate (H) at (1.2,0);
\draw (A) -- (B) node[midway,below] {$b$};
\draw (B) -- (C);
\draw (C) -- (D);
\draw (D) -- (A);
\draw[dashed] (D) -- (H) node[midway,right] {$h$};
\coordinate (ra) at ($(H)!0.3cm!(D)$);
\coordinate (rb) at ($(H)!0.3cm!(B)$);
\draw (ra) -- ($(ra)+(rb)-(H)$) -- (rb);
\coordinate (P) at (6.5,0);
