mastery.solution_text:
Extend base $AB$ beyond $B$. Draw the perpendicular from $C$ to this extended line.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc}
\coordinate (A) at (0,0);\coordinate (B) at (2,2);\coordinate (C) at (4,1);\coordinate (H) at (2.5,2.5);
\draw (A)--(B) node[midway,above left] {$AB$}--(C)--cycle;
\draw[dashed] (B)--(H);\draw[dashed] (C)--(H) node[midway,above right] {height};
\coordinate (ra) at ($(H)!0.25cm!(C)$);\coordinate (rb) at ($(H)!0.25cm!(B)$);\draw (ra)--($(ra)+(rb)-(H)$)--(rb);
\node[below left] at (A) {$A$};\node[above left] at (B) {$B$};\node[right] at (C) {$C$};
\end{tikzpicture}
[/tikz]
